{  ${\dfrac{8}{17}}$ }
   {  ${\dfrac{1}{2}}$ }
     { \True ${\dfrac{2}{5}}$  }
    { ${\dfrac{8}{19}}$  }
\loigiai{
$\Omega =  \left\{ \overline {ij}  ; 2 \le i;j \le 6 \right\} $\\
Số phần tử của không gian mẫu là $20$\\
$A=\left\{23; 26; 32; 35; 53; 56; 62; 65\right\} $\\
Số kết quả thuận lợi của biến cố là $8$\\
Xác suất là ${\dfrac{2}{5}}$
}\end{ex}

